export const normalize = text => text.normalize('NFKD').replace(/\p{M}/gu,'').replace(/[\u200B-\u200D\uFEFF]/g,'').toLowerCase();
export const normalizeForDetection = text => normalize(text).replace(/(?:\b[a-z0-9]\s+){2,}[a-z0-9]\b/g,match=>match.replace(/\s+/g,''));
export function tokens(text){const clean=normalize(text);const words=clean.match(/[a-z0-9]+/g)||[];const han=clean.match(/[\p{Script=Han}]+/gu)||[];for(const run of han){const chars=[...run];for(let i=0;i<chars.length;i++){words.push(chars[i]);if(i+1<chars.length)words.push(chars[i]+chars[i+1]);}}return words;}
const patterns={
 threat:/\b(deport\w*|arrest\w*|detain\w*|detention|detenido|detencion|expulsion|truc xuat|bat giu|visa.{0,20}cancel\w*|cancel\w*.{0,20}visa)\b|遣返|驱逐|逮捕|拘留|取消/,
 urgent:/\b(urgent\w*|immediately|today|within \d+ hours?|ahora|hoy|inmediatamente|ngay lap tuc|hom nay|khan cap|trong \d+ gio)\b|立即|马上|今天|紧急/,
 payment:/\b(pay\w*|send money|transfer\w*|fee\w*|paga\w*|pago\w*|envi[ae] dinero|tarifa\w*|cuota\w*|thanh toan|chuyen tien|nop phi|tra phi|tien)\b|付款|支付|转账|汇款|费用/,
 irreversible:/\b(g[i1]ft\s*cards?|bitcoin|crypto\w*|wire transfer|z[e3]lle|western union|moneygram|tarjetas? de regalo|criptomoneda\w*|the qua tang|tien dien tu)\b|礼品卡|比特币|加密货币/,
 sensitive:/\b(password\w*|verification code|one.time code|social security|bank details|passport number|contrasena\w*|codigo de verificacion|seguro social|numero de pasaporte|mat khau|ma xac minh|so ho chieu|tai khoan ngan hang)\b|密码|验证码|护照号码|银行账户|社会安全号码/,
 credential:/\b(sign[ -]?in|log[ -]?in|login|account.{0,40}(disabled|suspend\w*|lock\w*|expir\w*)|microsoft 365|office 365|google workspace)\b/,
 link:/(?:https?:\/\/|www\.)[^\s<>"']+|\b[a-z0-9][a-z0-9.-]*\.(?:com|org|net|gov|info|site|xyz|us|example)(?:\/[^\s<>"']*)?/,
 request:/\b(send|share|provide|confirm|verify|enter|reply|click|envi\w*|compart\w*|proporcion\w*|ingres\w*|verific\w*|gui|cung cap|nhap|xac minh|bam)\b|发送|提供|输入|确认|验证|点击/,
 agency:/\b(uscis|ice|immigration|visa|embassy|consulate|inmigracion|embajada|consulado|nhap cu|thi thuc|dai su quan)\b|移民|签证|领事馆|大使馆/,
 family:/\b(family|daughter|son|mother|father|relative|mum|mom|mama|reunification|familia\w*|hija|hijo|madre|padre|reunificacion|gia dinh|doan tu|con gai|con trai)\b|家人|女儿|儿子|母亲|父亲|妈妈|团聚/,
 secrecy:/\b(don.t tell|do not tell|keep.*secret|no le digas|no digas|secreto|dung noi|giu bi mat)\b|不要告诉|保密/,
 guarantee:/\b(guarantee\w*|guaranteed approval|garantiz\w*|dam bao|bao dam|chac chan.*duyet)\b|保证.*(签证|批准|绿卡)|包过/
};
export function suspiciousHosts(text){const candidates=text.match(/(?:https?:\/\/|www\.)[^\s<>"']+|\b[a-z0-9][a-z0-9.-]*\.(?:com|org|net|gov|info|site|xyz|us)(?:\/[^\s<>"']*)?/gi)||[];const flagged=[];for(const raw of candidates){try{const url=new URL(/^https?:/i.test(raw)?raw:'https://'+raw);const host=url.hostname.toLowerCase().replace(/\.$/,'');if(/uscis|(?:^|[.-])ice(?:[.-]|$)/.test(host)&&!['uscis.gov','ice.gov'].some(d=>host===d||host.endsWith('.'+d)))flagged.push(host);}catch{}}return [...new Set(flagged)];}
export function classify(text,model){if(!model)return {signal:'unavailable',knownTokens:0};const ts=tokens(text);const known=ts.filter(t=>Object.hasOwn(model.weights,t));if(known.length<3)return {signal:'insufficient',knownTokens:known.length};let score=model.bias;for(const t of known)score+=model.weights[t];return {signal:score>1.1?'scam-like':'inconclusive',knownTokens:known.length};}
export function isProtectiveAdvice(clean){
 const safetyTopic=/\b(scammers?|scam|fraud|warning|avoid|estafa|alerta|evita|lua dao|canh bao|tranh)\b|诈骗|警示|警告|避免|dau hieu/;
 const negatedPayment=/\b(never|do not|don't)\s+(pay|send)|\b(nunca|no)\s+(pagues|envies)|(?:^|\s)(?:dung|đung|khong|đừng|không)\s+(thanh toan|thanh toán|gui)|不要.{0,12}(付款|支付|汇款|礼品卡)/;
 const negatedSecret=/\b(do not|don't)\s+(send|share).{0,45}\b(password|verification code)\b|\bno\s+(compartas|envies).{0,45}\b(contrasena|codigo)\b|(?:^|\s)(?:dung|đung|khong|đừng|không)\s+(gui|gửi).{0,45}\b(mat khau|mật khẩu|ma xac minh|mã xác minh)\b|不要.{0,25}(发送|提供).{0,25}(密码|验证码)/;
 const educational=/\b(warning signs?|example|scammers? (?:may|might|often)|avoid|alerta|ejemplo|estafadores? (?:pueden|suelen)|canh bao|vi du)\b|警示|示例|诈骗者/;
 const directRequest=/\b(you must|please|send|pay now|click|reply|debes|paga ahora|envia|ban phai|gui ngay)\b|请立即|马上付款/;
 return (negatedPayment.test(clean)&&safetyTopic.test(clean))||negatedSecret.test(clean)||(safetyTopic.test(clean)&&educational.test(clean)&&!directRequest.test(clean));
}
export function analyze(text,model){if(typeof text!=='string'||!text.trim())throw new Error('empty');if(text.length>10000)throw new Error('long');const clean=normalizeForDetection(text);const hits=Object.fromEntries(Object.entries(patterns).map(([id,re])=>[id,clean.match(re)?.[0]||null]));const protective=isProtectiveAdvice(clean);const contactChange=/\b(changed my number|new number|numero nuevo|cambie mi numero|doi so|so moi|số mới)\b|(?:^|\s)đoi so\b|换号码|新号码/.exec(clean)?.[0]||null;const moneyAsk=/\b(cover|invoice|bill|factura|cubrir|cuenta|hoa don|hoa đơn|tra hoa don|tra hoa đon|trả hóa đơn)\b|账单/.exec(clean)?.[0]||null;const familyReference=hits.family||/(?:^|\s)me oi\b/.exec(clean)?.[0]||null;const findings=[];const add=(id,evidence)=>findings.push({id,evidence});if(!protective&&hits.threat&&(hits.payment||hits.request))add('threat',hits.threat);if(!protective&&hits.irreversible&&hits.payment)add('payment',hits.irreversible);if(!protective&&hits.sensitive&&hits.request)add('sensitive',hits.sensitive);if(!protective&&hits.credential&&hits.urgent&&hits.link)add('sensitive',hits.credential);if(!protective&&hits.urgent&&(hits.payment||hits.sensitive))add('urgency',hits.urgent);if(!protective&&hits.agency&&hits.payment&&hits.request)add('agency',hits.agency);if(!protective&&hits.family&&hits.payment&&(hits.urgent||hits.secrecy||hits.threat))add('family',hits.family);if(!protective&&familyReference&&contactChange&&moneyAsk)add('impersonation',contactChange);if(!protective&&hits.guarantee&&hits.agency)add('guarantee',hits.guarantee);for(const host of suspiciousHosts(text))add('domain',host);const ml=classify(text,model);const modelCanElevate=!protective&&(hits.request||hits.threat||(hits.irreversible&&hits.payment));const strong=findings.some(f=>['threat','payment','domain','guarantee'].includes(f.id));const level=strong?'high':findings.length||(ml.signal==='scam-like'&&modelCanElevate)?'review':'unknown';return {level,findings,model:ml,protective};}
